const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const ROOT = path.resolve(__dirname, "..");
const DB_PATH = path.join(ROOT, ".cortex", "cyrene-memory.db");
/** 生成一384 维的 dummy embedding，避ONNX 模型加载 */
function dummyEmbedding() {
    // 使用日期哈希作为种子，确保写入时有非embedding
    const seed = Date.now();
    const arr = new Array(384);
    for (let i = 0; i < 384; i++) {
        arr[i] = Math.sin(seed + i * 0.01) * 0.01;
    }
    return arr;
}
